import os
import boto3

def conditional_update(payload, config=None):
    config = config or {}
    dynamodb_client = boto3.client('dynamodb', region_name=os.environ.get('AWS_REGION', 'us-east-1'))
    table_name = os.environ.get("DYNAMODB_TABLE_NAME", "my-documents-table")

    item_id = payload.get('id')
    if not item_id:
        raise ValueError("Payload must contain an 'id' for the document.")

    current_version = payload.get('_version')
    if current_version is None:
        raise ValueError("Payload must contain a '_version' for a version-aware update.")

    update_expression_parts = []
    expression_attribute_values = {
        ':expected_version': current_version,
        ':new_version': current_version + 1
    }

    for key, value in payload.items():
        if key not in ['id', '_version']:
            update_expression_parts.append(f"{key} = :{key_alias}")
            expression_attribute_values[f':{key_alias}'] = value

    # Generate an update expression that sets all provided fields and increments _version
    # This also sets a default value for _version if it doesn't exist (creating the item)
    update_expression_str = "SET " + ", ".join(update_expression_parts)
    if not update_expression_parts: # If no other attributes are updated, ensure _version is still incremented
        update_expression_str = "SET _version = :new_version"
    else:
        update_expression_str += ", _version = :new_version"

    # Define the condition for the update: _version must match the expected value
    condition_expression_str = "_version = :expected_version"

    # Convert Python types to DynamoDB attribute value format
    dynamodb_attribute_values = {}
    for k, v in expression_attribute_values.items():
        if isinstance(v, str):
            dynamodb_attribute_values[k] = {'S': v}
        elif isinstance(v, bool):
            dynamodb_attribute_values[k] = {'BOOL': v}
        elif isinstance(v, (int, float)):
            dynamodb_attribute_values[k] = {'N': str(v)}
        elif isinstance(v, list):
            # For simplicity, assuming list of strings/numbers. A full marshaller would be more complex.
            dynamodb_attribute_values[k] = {'L': [{'S': str(item)} for item in v]}
        elif isinstance(v, dict):
            # For simplicity, assuming dictionary of strings/numbers.
            dynamodb_attribute_values[k] = {'M': {inner_k: {'S': str(inner_v)} for inner_k, inner_v in v.items()}}
        else: # Fallback for other types, attempt to convert to string
            dynamodb_attribute_values[k] = {'S': str(v)}

    try:
        response = dynamodb_client.update_item(
            TableName=table_name,
            Key={'id': {'S': item_id}},
            UpdateExpression=update_expression_str,
            ConditionExpression=condition_expression_str,
            ExpressionAttributeValues=dynamodb_attribute_values,
            ReturnValues='ALL_NEW'
        )

        # Parse DynamoDB's attribute value format back to Python types
        returned_attributes = response.get('Attributes', {})
        normalized_result = {}
        for k, v in returned_attributes.items():
            if 'S' in v:
                normalized_result[k] = v['S']
            elif 'N' in v:
                val_str = v['N']
                if '.' in val_str:
                    normalized_result[k] = float(val_str)
                else:
                    normalized_result[k] = int(val_str)
            elif 'BOOL' in v:
                normalized_result[k] = v['BOOL']
            elif 'L' in v: # Example for list
                normalized_result[k] = [item['S'] if 'S' in item else item.get('N') for item in v['L']]
            elif 'M' in v: # Example for map
                normalized_result[k] = {inner_k: inner_v['S'] if 'S' in inner_v else inner_v.get('N') for inner_k, inner_v in v['M'].items()}
            # Add more types (B, SS, NS, BS, NULL) as needed
            else:
                normalized_result[k] = v # Fallback
        result = normalized_result
    except dynamodb_client.exceptions.ConditionalCheckFailedException:
        print(f"Conditional update failed: Item with id '{item_id}' does not exist or its version does not match {current_version}.")
        result = None # Indicate failure due to condition
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        raise # Re-raise other exceptions
    return result
